function scoreMarkets(profile,nCities=12){
  const cap=profile.estimated_capacity||1e3,guar=profile.estimated_guarantee||1e4;
  const scored=MARKETS.map(mkt=>{
    const capRatio=mkt.mc>0?Math.min(cap,mkt.mc)/Math.max(cap,mkt.mc):0.3;
    const tierDiff=Math.abs(mkt.t-(guar>2e5?3:guar>5e4?2:guar>5e3?1:0));
    const fillBase=mkt.af>0?mkt.af:0.5;
    const fillProb=Math.min(1,fillBase*(1-tierDiff*0.15));
    const revenueRatio=guar/Math.max(mkt.ag||5e3,1);
    const predRevenue=Math.max(0,mkt.an*Math.min(revenueRatio,3)*(0.5+fillProb*0.5));
    const predCapacity=Math.max(100,cap*(0.7+capRatio*0.6));
    const strengthScore=Math.min(100,mkt.na*30+mkt.ns*5);
    const score=fillProb*30+(predRevenue>0?Math.min(100,(predRevenue/Math.max(guar*1.5,1))*100)*0.25:0)+strengthScore*0.25+capRatio*20;
    return{rank:0,city:mkt.c,state:mkt.s,market:mkt.m,country:"US",market_score:Math.round(score*10)/10,confidence:Math.round(fillProb*100)/100,predicted_capacity:Math.round(predCapacity),predicted_net_revenue:Math.round(predRevenue),predicted_fill_probability:Math.round(fillProb*100)/100,has_artist_history:false,historical:null,reasoning:[fillProb>.7?`High fill probability (${pct(fillProb)})`:null,mkt.na>=2?`Strong market (${mkt.na} artists)`:null,capRatio>.6?"Good capacity match":null,predRevenue>guar?"Above-average revenue":null].filter(Boolean).join(". ")+"."||"Recommended by cross-artist model."};
  }).filter(m=>m.market_score>10).sort((a,b)=>b.market_score-a.market_score).slice(0,nCities);
  scored.forEach((m,i)=>m.rank=i+1);
  const getC=m=>COORDS[m]||[39.8,-98.6];
  const dist=(a,b)=>Math.sqrt((a[0]-b[0])**2+(a[1]-b[1])**2)*69;
  const mkts=scored.map(m=>m.market);
  const vis=[0];const rem=new Set(mkts.map((_,i)=>i));rem.delete(0);
  while(rem.size>0){const cur=vis[vis.length-1];let best=-1,bestD=1/0;for(const r of rem){const d=dist(getC(mkts[cur]),getC(mkts[r]));if(d<bestD){bestD=d;best=r;}}vis.push(best);rem.delete(best);}
  const totalDist=vis.reduce((s,v,i)=>i===0?0:s+dist(getC(mkts[vis[i-1]]),getC(mkts[v])),0);
  return{artist:profile.artist_name,profile_source:"ai_estimated",artist_profile:{growth_phase:profile.growth_phase||"club",current_avg_capacity:cap,current_avg_guarantee:guar,avg_fill_rate:profile.estimated_fill_rate||0.7,guarantee_cagr:0,total_headline_shows:0,n_markets_played:0},recommendation_config:{optimize_for:"balanced",region:"us",n_requested:nCities},markets:scored,route:{routed_markets:vis.map(i=>mkts[i]),total_distance_miles:Math.round(totalDist),start_city:mkts[0]},financial_summary:{total_predicted_net:scored.reduce((s,m)=>s+m.predicted_net_revenue,0),avg_predicted_capacity:Math.round(scored.reduce((s,m)=>s+m.predicted_capacity,0)/scored.length),avg_predicted_fill_prob:Math.round(scored.reduce((s,m)=>s+m.predicted_fill_probability,0)/scored.length*100)/100},model_metadata:{n_training_shows:221,n_training_artists:2,markets_in_model:MARKETS.length,top_features:{avg_artist_net:.26,avg_capacity:.12,avg_guarantee:.11,headline_shows:.08,avg_fill_rate:.07}},ai_summary:profile.summary||null,comparable_artists:profile.comparable_artists||[]};
}

